<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}require dirname(__DIR__,3).'/config/config.inc.php';$db=Db::getInstance();$rows=$db->executeS("SELECT * FROM `"._DB_PREFIX_."ntcr_outbox` WHERE status IN ('pending','failed') AND next_attempt_at<=NOW() AND attempts<5 ORDER BY id_outbox LIMIT 20");foreach($rows as $r){$payload=json_decode($r['payload_json'],true);$subject='Yeni yayıncı talebi: '.($payload['request_no']??'');$body='<p>Talep: '.htmlspecialchars($payload['request_no']??'').'</p><p>Tür: '.htmlspecialchars($payload['type']??'').'</p><p>Yayıncı: @'.htmlspecialchars($payload['publisher']??'').'</p><p>Puan: '.number_format((int)($payload['points']??0),0,',','.').'</p>';try{$ok=Mail::Send((int)Configuration::get('PS_LANG_DEFAULT'),'contact',$subject,array('{message}'=>$body),$r['recipient'],null,null,null,null,null,_PS_MODULE_DIR_.'ntcreatorrewards/mails/');if(!$ok)throw new RuntimeException('Mail::Send false');$db->update('ntcr_outbox',array('status'=>'sent','attempts'=>(int)$r['attempts']+1,'date_sent'=>date('Y-m-d H:i:s'),'last_error'=>null),'id_outbox='.(int)$r['id_outbox']);}catch(Exception $e){$db->update('ntcr_outbox',array('status'=>'failed','attempts'=>(int)$r['attempts']+1,'next_attempt_at'=>date('Y-m-d H:i:s',time()+900),'last_error'=>pSQL(substr($e->getMessage(),0,500),true)),'id_outbox='.(int)$r['id_outbox']);}}
$due=$db->executeS("SELECT * FROM `"._DB_PREFIX_."ntcr_explore_job` WHERE status='manual_queue' AND scheduled_at_utc<=UTC_TIMESTAMP() ORDER BY scheduled_at_utc LIMIT 20");foreach($due as $j){$db->update('ntcr_explore_job',array('status'=>'review','date_upd'=>date('Y-m-d H:i:s'),'last_error'=>'Manuel uygulama bekliyor; otomatik entegrasyon etkin değil.'),'id_job='.(int)$j['id_job']);$db->update('ntcr_request',array('status'=>'review','date_upd'=>date('Y-m-d H:i:s')),'id_request='.(int)$j['id_request']." AND status='scheduled'");}echo 'outbox='.count($rows).' explore='.count($due).PHP_EOL;
